define "Most Recent BMI":
  First([USCore.BMIProfile] BMI
      where BMI.status in { 'final', 'amended', 'corrected' }
      sort by start of effective.toInterval() desc
  )

define "SDE Race":
  (Patient.race()) R
    return Tuple {
      codes: R.ombCategory union R.detailed,
      display: R.text
    }

define "SDE Payer":
  [USQualityCore.Coverage: type in "Payer Type"] Payer
    return {
      code: Payer.type,
      period: Payer.period
    }

define "SDE Ethnicity":
  (Patient.ethnicity()) E
    return Tuple {
      codes: { E.ombCategory } union E.detailed,
      display: E.text
    }

define "Has Pregnancy Diagnosis During Measurement Period":
  // [E-13] base FHIR.Condition retrieve (defect-tracking/engine-issues.md E-13)
  // Original:
  //   ( ( [ConditionProblemsHealthConcerns: "Pregnancy"]
  //       union [ConditionEncounterDiagnosis: "Pregnancy"]
  //   ).verified ( ) )
  ( ( [FHIR.Condition: "Pregnancy"] ).verified ( ) ) PregnancyDx
    where PregnancyDx.prevalenceInterval ( ) overlaps day of "Measurement Period"

define "Has Advanced Illness or Limited Life Expectancy":
  // [E-13] base FHIR.Condition retrieves (defect-tracking/engine-issues.md E-13)
  // Original:
  //   ( ( ["ConditionProblemsHealthConcerns": "Advanced Illness"]
  //       union ["ConditionEncounterDiagnosis": "Advanced Illness"]
  //       union ["ConditionProblemsHealthConcerns": "Limited Life Expectancy"]
  //       union ["ConditionEncounterDiagnosis": "Limited Life Expectancy"]
  //   ).verified ( ) )
  ( ( [FHIR.Condition: "Advanced Illness"]
      union [FHIR.Condition: "Limited Life Expectancy"]
  ).verified ( ) ) AdvancedIllness
    where "AdvancedIllness".onset before day of end of "Measurement Period"

define "Diabetes Diagnosis Overlaps 2 Year Look Back Period":
  // [E-13] base FHIR.Condition retrieve (defect-tracking/engine-issues.md E-13)
  // Original:
  //   ( ( ["ConditionProblemsHealthConcerns": "Diabetes"]
  //       union ["ConditionEncounterDiagnosis": "Diabetes"]
  //   ).verified ( ) )
  ( ( [FHIR.Condition: "Diabetes"] ).verified ( ) ) PriorDiabetes
    where "PriorDiabetes".prevalenceInterval ( ) overlaps day of "Look Back Period"

define "Prediabetes Diagnosis Overlaps 2 Year Look Back Period":
  // [E-13] base FHIR.Condition retrieve (defect-tracking/engine-issues.md E-13)
  // Original:
  //   ( ( ["ConditionProblemsHealthConcerns": "Prediabetes (Borderline Diabetes)"]
  //       union ["ConditionEncounterDiagnosis": "Prediabetes (Borderline Diabetes)"]
  //   ).verified ( ) )
  ( ( [FHIR.Condition: "Prediabetes (Borderline Diabetes)"] ).verified ( ) ) PriorPrediabetes
    where "PriorPrediabetes".prevalenceInterval ( ) overlaps day of "Look Back Period"

define "Has Glycemic Laboratory Test Performed During 2 Year Look Back Period":
  exists ( [LaboratoryResultObservation: "Glycemic Screening Tests"] LabTestPerformed
      where CQMCommon.ToDateInterval ( LabTestPerformed.effective ) during day of "Look Back Period"
        and LabTestPerformed.status in { 'final', 'amended', 'corrected' }
  )

/*
@description: Returns the sex element as defined for the USCore patient profile
*/
define fluent function sex(patient Patient):
  patient.ext('http://hl7.org/fhir/us/core/StructureDefinition/us-core-sex').value as FHIR.code

/*
@description: Returns the single extension (if present) on the given resource with the specified url.
@comment: This function uses singleton from to ensure that a run-time exception is thrown if there
is more than one extension on the given resource with the specified url.
*/
define fluent function ext(domainResource DomainResource, url String):
  singleton from domainResource.exts(url)

/*
@description: Returns an interval of date values extracted from the input interval of date-time values
@comment: This function returns an interval constructed using the `date from` extractor on the start
and end values of the input date-time interval. Note that using a precision specifier such as `day of`
as part of a timing phrase is preferred to communicate intent to perform day-level comparison, as well
as for general readability.
*/
define function "ToDateInterval"(period Interval<DateTime>):
  Interval[date from start of period, date from end of period]

/*
@description: Returns the single extension (if present) on the given element with the specified url.
@comment: This function uses singleton from to ensure that a run-time exception is thrown if there
is more than one extension on the given element with the specified url.
*/
define fluent function ext(element Element, url String):
  singleton from element.exts(url)

/*
@description: Converts the given FHIR [Coding](https://hl7.org/fhir/datatypes.html#Coding) value to a CQL Code.
*/
define function ToCode(coding FHIR.Coding):
    if coding is null then
        null
    else
        System.Code {
          code: coding.code.value,
          system: coding.system.value,
          version: coding.version.value,
          display: coding.display.value
        }

/*
@description: Converts the given FHIR [CodeableConcept](https://hl7.org/fhir/datatypes.html#CodeableConcept) value to a CQL Concept.
*/
define function ToConcept(concept FHIR.CodeableConcept):
    if concept is null then
        null
    else
        System.Concept {
            codes: concept.coding C return ToCode(C),
            display: concept.text.value
        }
